input.command:
date; cd <tmp>/904c52d9-f200-4552-8ce5-05e400952efa/scratchpad/r6b && cat > app1.mjs <<'EOF'
import { createRequire } from "module"; const { chromium } = createRequire("<project>/flare/node_modules/")("playwright-core");
const b = await chromium.launch({ channel: "chrome" });
const c = await b.newContext({ viewport:{width:390,height:844}, hasTouch:true, isMobile:true, deviceScaleFactor:2, extraHTTPHeaders:{"x-flare-test":"1"} });
const p = await c.newPage();
p.on("console", m=>{ if(m.type()==="error") console.log("CONSOLE ERR", m.text())});
await p.goto("https://flare-outside.onrender.com/app/", {waitUntil:"networkidle", timeout:90000});
